#[allow(dead_code)] // The analysis API is also used by the benchmark executables.
mod analysis;
#[allow(dead_code)] // Resident replay is an analysis benchmark operation.
mod cuda;
#[allow(dead_code)] // Calibration and indexed operations share this implementation.
mod executor;
mod frontend;
mod ir;
mod llvm;
mod metal;
#[allow(dead_code)] // Profiles are generated by the native benchmark executable.
mod routing;

use std::{
    env, fs,
    io::{self, BufRead, Write},
    path::{Path, PathBuf},
    process::{self, Command},
    sync::Arc,
    time::Instant,
};

#[derive(Clone, Copy, Debug)]
enum Backend {
    Cpu,
    Metal,
    Hybrid,
    Cuda,
    CudaHybrid,
}
impl Backend {
    fn parse(value: &str) -> Result<Self, String> {
        match value {
            "cpu" => Ok(Self::Cpu),
            "metal" => Ok(Self::Metal),
            "hybrid" => Ok(Self::Hybrid),
            "cuda" => Ok(Self::Cuda),
            "cuda-hybrid" => Ok(Self::CudaHybrid),
            _ => Err(format!(
                "Unsupported native backend {value}; choose cpu, metal, hybrid, cuda, or cuda-hybrid"
            )),
        }
    }
    fn name(self) -> &'static str {
        match self {
            Self::Cpu => "cpu",
            Self::Metal => "metal",
            Self::Hybrid => "hybrid",
            Self::Cuda => "cuda",
            Self::CudaHybrid => "cuda-hybrid",
        }
    }
}
struct Options {
    source: Option<PathBuf>,
    emit: Option<PathBuf>,
    output: Option<PathBuf>,
    report: Option<PathBuf>,
    backend: Option<Backend>,
    shader: PathBuf,
    serve: bool,
    verify: bool,
    cuda_library: PathBuf,
    cuda_algorithm: cuda::Algorithm,
    route_profile: Option<PathBuf>,
    objective: String,
    cpu_workers: usize,
}
fn options() -> Result<Option<Options>, String> {
    let mut result = Options {
        source: None,
        emit: None,
        output: None,
        report: None,
        backend: None,
        shader: Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap()
            .join("src/liveness.metal"),
        serve: false,
        verify: false,
        cuda_library: env::var_os("GPU_LAB_CUDA_LIBRARY")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(".build/cuda/libgpulab_cuda.so")),
        cuda_algorithm: cuda::Algorithm::Dense,
        route_profile: None,
        objective: "latency".into(),
        cpu_workers: 0,
    };
    let mut arguments = env::args().skip(1);
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--help" | "-h" => {
                println!("Usage: gpu-rust-compiler SOURCE.rs --output EXECUTABLE --backend cpu|metal|hybrid|cuda|cuda-hybrid [--verify] [--emit-llvm FILE] [--report FILE]");
                println!("       gpu-rust-compiler --serve --backend cpu|metal|hybrid|cuda|cuda-hybrid [--verify] [--shader FILE]");
                println!("CUDA options: --cuda-library LIBRARY --cuda-algorithm dense|sparse --route-profile PROFILE --mode latency|throughput");
                println!("CPU options: --cpu-workers COUNT (0 uses available CPUs)");
                println!("Worker input: compile<TAB>SOURCE<TAB>OUTPUT<TAB>REPORT (REPORT may be empty). One JSON response per request.");
                println!("Raw frontend compatibility: SOURCE.rs --emit-llvm FILE (without --backend or --output).");
                return Ok(None);
            }
            "--serve" => result.serve = true,
            "--verify" => result.verify = true,
            "--cuda-library" => {
                result.cuda_library =
                    PathBuf::from(arguments.next().ok_or("Missing CUDA library path")?)
            }
            "--cuda-algorithm" => {
                result.cuda_algorithm =
                    match arguments.next().ok_or("Missing CUDA algorithm")?.as_str() {
                        "dense" => cuda::Algorithm::Dense,
                        "sparse" => cuda::Algorithm::Sparse,
                        value => return Err(format!("Unsupported CUDA algorithm {value}")),
                    }
            }
            "--route-profile" => {
                result.route_profile = Some(PathBuf::from(
                    arguments.next().ok_or("Missing route profile path")?,
                ))
            }
            "--cpu-workers" => {
                result.cpu_workers = arguments
                    .next()
                    .ok_or("Missing CPU worker count")?
                    .parse::<usize>()
                    .map_err(|_| "Invalid CPU worker count")?
            }
            "--mode" => {
                result.objective = arguments.next().ok_or("Missing execution mode")?;
                if !matches!(result.objective.as_str(), "latency" | "throughput") {
                    return Err("Execution mode must be latency or throughput".into());
                }
            }
            "--emit-llvm" => {
                result.emit = Some(PathBuf::from(arguments.next().ok_or("Missing LLVM path")?))
            }
            "--output" => {
                result.output = Some(PathBuf::from(
                    arguments.next().ok_or("Missing executable path")?,
                ))
            }
            "--report" => {
                result.report = Some(PathBuf::from(
                    arguments.next().ok_or("Missing report path")?,
                ))
            }
            "--shader" => {
                result.shader = PathBuf::from(arguments.next().ok_or("Missing shader path")?)
            }
            "--backend" => {
                result.backend = Some(Backend::parse(&arguments.next().ok_or("Missing backend")?)?)
            }
            _ if !argument.starts_with('-') && result.source.is_none() => {
                result.source = Some(PathBuf::from(argument))
            }
            _ => return Err(format!("Unknown option {argument}")),
        }
    }
    if !result.serve && result.source.is_none() {
        return Err("A source path or --serve is required".into());
    }
    if result.serve && result.source.is_some() {
        return Err("--serve receives source paths through stdin".into());
    }
    Ok(Some(result))
}
fn ensure_parent(path: &Path) -> Result<(), String> {
    if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        fs::create_dir_all(parent).map_err(|e| e.to_string())?;
    }
    Ok(())
}
fn json_string(text: &str) -> String {
    let mut result = String::from("\"");
    for ch in text.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            ch if ch < '\u{20}' => result.push_str(&format!("\\u{:04x}", ch as u32)),
            ch => result.push(ch),
        }
    }
    result.push('"');
    result
}
fn ms(start: Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1000.0
}
struct Report {
    backend: Backend,
    source: PathBuf,
    output: PathBuf,
    request: usize,
    total: f64,
    frontend: f64,
    packing: f64,
    analysis: f64,
    pruning: f64,
    codegen: f64,
    removed: usize,
    functions: usize,
    cpu_functions: usize,
    gpu_functions: usize,
    verified: bool,
    pipeline_creations: usize,
    gpu_submissions: usize,
    gpu: Option<metal::Stats>,
    cuda: Option<cuda::Stats>,
    cuda_capabilities: Option<cuda::Capabilities>,
    cpu_workers: usize,
    cpu_requests: usize,
    cpu_pool_reused: bool,
    cpu_pool_submissions: usize,
    cpu_initialization: f64,
    routing_reason: String,
    objective: String,
    cuda_algorithm: cuda::Algorithm,
}
impl Report {
    fn json(&self) -> String {
        let (gpu_ms, reused, allocations, sweeps) = if let Some(gpu) = self.cuda {
            (
                format!("{:.6}", gpu.gpu_ms),
                gpu.reused_context != 0,
                gpu.device_allocations,
                gpu.max_sweeps,
            )
        } else if let Some(gpu) = self.gpu {
            (
                format!("{:.6}", gpu.gpu_ms),
                gpu.reused_pipeline != 0,
                gpu.buffer_allocations,
                gpu.max_sweeps,
            )
        } else {
            ("null".into(), false, 0, 0)
        };
        let mut result = format!(concat!(
            "{{\"status\":\"ok\",\"compiler\":\"native scalar Rust-subset compiler\",",
            "\"backend\":{},\"source\":{},\"output\":{},\"process_id\":{},\"request_number\":{},",
            "\"total_compile_ms\":{:.6},\"frontend_and_structured_ir_ms\":{:.6},\"native_packing_ms\":{:.6},",
            "\"analysis_ms\":{:.6},\"dead_code_pruning_ms\":{:.6},\"native_codegen_and_link_ms\":{:.6},",
            "\"dead_scalar_instructions_removed\":{},\"functions\":{},\"cpu_functions\":{},\"actual_gpu_functions\":{},",
            "\"verified_against_cpu\":{},\"gpu_pipeline_creations\":{},\"gpu_submissions_total\":{},",
            "\"gpu_execution_ms\":{},\"gpu_pipeline_reused\":{},\"gpu_buffer_allocations\":{},\"gpu_max_sweeps\":{},",
            "\"analysis_transport\":\"native memory; no textual IR parsing, JSON handoff, or analysis subprocess\",",
            "\"remaining_codegen_subprocess\":\"clang\"}}"),
            json_string(self.backend.name()), json_string(&self.source.to_string_lossy()), json_string(&self.output.to_string_lossy()),
            process::id(), self.request, self.total, self.frontend, self.packing, self.analysis, self.pruning, self.codegen,
            self.removed, self.functions, self.cpu_functions, self.gpu_functions, self.verified,
            self.pipeline_creations, self.gpu_submissions, gpu_ms, reused, allocations, sweeps);
        result.pop();
        result.push_str(&format!(concat!(
            ",\"cpu_worker_threads\":{},\"cpu_worker_pool_creations\":1,\"cpu_requests_total\":{},",
            "\"cpu_pool_reused\":{},\"cpu_pool_submissions\":{},\"cpu_initialization_ms\":{:.6},\"routing_reason\":{},",
            "\"execution_objective\":{},\"cuda_algorithm\":{},\"cuda_stats\":{},\"cuda_capabilities\":{}}}"),
            self.cpu_workers, self.cpu_requests, self.cpu_pool_reused, self.cpu_pool_submissions, self.cpu_initialization,
            json_string(&self.routing_reason), json_string(&self.objective),
            json_string(match self.cuda_algorithm { cuda::Algorithm::Dense => "dense", cuda::Algorithm::Sparse => "sparse" }),
            self.cuda.map_or_else(|| "null".into(), |stats| stats.json()),
            self.cuda_capabilities.as_ref().map_or_else(|| "null".into(), |capabilities| capabilities.json())));
        result
    }
}
struct Compiler {
    backend: Backend,
    shader: PathBuf,
    verify: bool,
    metal: Option<metal::Context>,
    pipeline_creations: usize,
    requests: usize,
    cpu: executor::CpuExecutor,
    cuda: Option<cuda::Context>,
    cuda_library: PathBuf,
    cuda_algorithm: cuda::Algorithm,
    route_profile: Option<PathBuf>,
    objective: String,
}
impl Compiler {
    fn new(options: &Options) -> Self {
        Self {
            backend: options.backend.unwrap_or(Backend::Hybrid),
            shader: options.shader.clone(),
            verify: options.verify,
            metal: None,
            pipeline_creations: 0,
            requests: 0,
            cpu: executor::CpuExecutor::new(options.cpu_workers),
            cuda: None,
            cuda_library: options.cuda_library.clone(),
            cuda_algorithm: options.cuda_algorithm,
            route_profile: options.route_profile.clone(),
            objective: options.objective.clone(),
        }
    }
    fn gpu(&mut self) -> Result<&mut metal::Context, String> {
        if self.metal.is_none() {
            self.metal = Some(metal::Context::new(&self.shader)?);
            self.pipeline_creations += 1;
        }
        Ok(self.metal.as_mut().unwrap())
    }
    fn cuda_gpu(&mut self) -> Result<&mut cuda::Context, String> {
        if self.cuda.is_none() {
            self.cuda = Some(
                cuda::Context::new(&self.cuda_library)
                    .map_err(|error| format!("CUDA adapter unavailable: {error}"))?,
            );
            self.pipeline_creations += 1;
        }
        Ok(self.cuda.as_mut().unwrap())
    }
    fn compile(
        &mut self,
        source: &Path,
        output: &Path,
        emit: Option<&Path>,
        report: Option<&Path>,
    ) -> Result<Report, String> {
        self.requests += 1;
        let start = Instant::now();
        let source_text =
            fs::read_to_string(source).map_err(|e| format!("{}: {e}", source.display()))?;
        let program = frontend::parse(&source_text)?;
        let module = llvm::emit_structured(&program)?;
        let frontend = ms(start);
        let stage = Instant::now();
        let packed = Arc::new(analysis::prepare(&module)?);
        let packing = ms(stage);
        let stage = Instant::now();
        let mut cpu_functions = module.functions.len();
        let mut gpu_functions = 0;
        let mut gpu_stats = None;
        let mut cuda_stats = None;
        let mut selected_cuda_algorithm = self.cuda_algorithm;
        let mut routing_reason = "Explicit backend selection".to_string();
        let solution = match self.backend {
            Backend::Cpu => self.cpu.solve(Arc::clone(&packed)),
            Backend::Cuda => {
                let algorithm = self.cuda_algorithm;
                self.cuda_gpu()?.submit(&packed, algorithm)?;
                let (solution, stats) = self.cuda_gpu()?.finish()?;
                cpu_functions = 0;
                gpu_functions = module.functions.len();
                cuda_stats = Some(stats);
                solution
            }
            Backend::CudaHybrid => {
                if let Some(path) = self.route_profile.as_ref() {
                    let profile = routing::RouteProfile::load(path)?;
                    let objective = if self.objective == "throughput" {
                        routing::Objective::Throughput
                    } else {
                        routing::Objective::Latency
                    };
                    // Check shape eligibility before paying for CUDA startup.
                    // Actual hardware identity is checked before any GPU work;
                    // this preliminary plan cannot authorize a submission.
                    if profile
                        .plan(&packed, &profile.hardware_identity, objective)
                        .gpu_indices
                        .is_empty()
                    {
                        routing_reason =
                            "No measured GPU win for this workload and objective; CPU selected"
                                .into();
                        self.cpu.solve(Arc::clone(&packed))
                    } else {
                        let workers = self.cpu.workers();
                        let capabilities = self.cuda_gpu()?.capabilities();
                        let identity =
                            routing::hardware_identity(&capabilities.fingerprint(workers), workers);
                        let plan = profile.plan(&packed, &identity, objective);
                        routing_reason = plan.reason;
                        if plan.gpu_indices.is_empty() {
                            if let Some(workers) = plan.cpu_worker_limit {
                                self.cpu.set_worker_limit(&packed, plan.cpu_mode, workers)?;
                            }
                            self.cpu.solve_mode(Arc::clone(&packed), plan.cpu_mode)
                        } else {
                            let selected = analysis::select_packed(&packed, &plan.gpu_indices)?;
                            let cpu_selection =
                                executor::AnalysisSelection::new(&packed, &plan.cpu_indices)?;
                            let algorithm = match plan.algorithm {
                                routing::GpuAlgorithm::Dense => cuda::Algorithm::Dense,
                                routing::GpuAlgorithm::Sparse => cuda::Algorithm::Sparse,
                            };
                            selected_cuda_algorithm = algorithm;
                            self.cuda_gpu()?.submit(&selected, algorithm)?;
                            // Independent CPU functions execute after submission,
                            // while the CUDA stream owns its input snapshot.
                            let workers = plan
                                .cpu_worker_limit
                                .unwrap_or_else(|| self.cpu.worker_limit(&packed, plan.cpu_mode));
                            let cpu_values = self.cpu.solve_selection_with_workers(
                                Arc::clone(&packed),
                                &cpu_selection,
                                plan.cpu_mode,
                                workers,
                            );
                            let (gpu_values, stats) = self.cuda_gpu()?.finish()?;
                            let mut values = vec![0; packed.total_cells];
                            cpu_values.scatter_into(&mut values)?;
                            analysis::scatter(&selected, &gpu_values, &packed, &mut values)?;
                            cpu_functions = plan.cpu_indices.len();
                            gpu_functions = plan.gpu_indices.len();
                            cuda_stats = Some(stats);
                            values
                        }
                    }
                } else {
                    routing_reason = "No measured route profile; CPU selected".into();
                    self.cpu.solve(Arc::clone(&packed))
                }
            }
            Backend::Metal => {
                self.gpu()?.submit(&packed)?;
                let (solution, stats) = self.gpu()?.finish()?;
                cpu_functions = 0;
                gpu_functions = module.functions.len();
                gpu_stats = Some(stats);
                solution
            }
            Backend::Hybrid => {
                let plan = analysis::hybrid_plan(&packed);
                routing_reason = format!("Metal hybrid: {}", plan.reason);
                if plan.gpu_indices.is_empty() {
                    self.cpu.solve(Arc::clone(&packed))
                } else {
                    let gpu_pack = analysis::prepare_subset(&module, &plan.gpu_indices)?;
                    let cpu_pack = Arc::new(analysis::prepare_subset(&module, &plan.cpu_indices)?);
                    self.gpu()?.submit(&gpu_pack)?;
                    let cpu_values = self.cpu.solve(Arc::clone(&cpu_pack));
                    let (gpu_values, stats) = self.gpu()?.finish()?;
                    let mut result = vec![0; packed.total_cells];
                    analysis::scatter(&cpu_pack, &cpu_values, &packed, &mut result)?;
                    analysis::scatter(&gpu_pack, &gpu_values, &packed, &mut result)?;
                    cpu_functions = plan.cpu_indices.len();
                    gpu_functions = plan.gpu_indices.len();
                    gpu_stats = Some(stats);
                    result
                }
            }
        };
        if self.verify && solution != analysis::solve_cpu_serial(&packed) {
            return Err("Native selected-backend liveness disagrees with CPU oracle".into());
        }
        let analysis = ms(stage);
        let stage = Instant::now();
        let (optimized, removed) = analysis::prune(&module, &packed, &solution)?;
        let pruning = ms(stage);
        let stage = Instant::now();
        let ir_path = emit
            .map(Path::to_owned)
            .unwrap_or_else(|| output.with_extension("native.ll"));
        ensure_parent(&ir_path)?;
        ensure_parent(output)?;
        fs::write(&ir_path, optimized).map_err(|e| e.to_string())?;
        let generated = Command::new("clang")
            .args(["-Wno-override-module", "-O0"])
            .arg(&ir_path)
            .arg("-o")
            .arg(output)
            .output()
            .map_err(|e| format!("clang: {e}"))?;
        if !generated.status.success() {
            return Err(format!(
                "Native code generation failed: {}",
                String::from_utf8_lossy(&generated.stderr)
            ));
        }
        let codegen = ms(stage);
        let result = Report {
            backend: self.backend,
            source: source.to_owned(),
            output: output.to_owned(),
            request: self.requests,
            total: ms(start),
            frontend,
            packing,
            analysis,
            pruning,
            codegen,
            removed,
            functions: module.functions.len(),
            cpu_functions,
            gpu_functions,
            verified: self.verify,
            pipeline_creations: self.pipeline_creations,
            gpu_submissions: self.metal.as_ref().map_or(0, |gpu| gpu.submissions)
                + self.cuda.as_ref().map_or(0, |gpu| gpu.submissions),
            gpu: gpu_stats,
            cuda: cuda_stats,
            cuda_capabilities: self.cuda.as_ref().map(|context| context.capabilities()),
            cpu_workers: self.cpu.workers(),
            cpu_requests: self.cpu.requests(),
            cpu_pool_reused: self.cpu.pool_reused(),
            cpu_pool_submissions: self.cpu.pool_submissions(),
            cpu_initialization: self.cpu.initialization_ms(),
            routing_reason,
            objective: self.objective.clone(),
            cuda_algorithm: selected_cuda_algorithm,
        };
        if let Some(path) = report {
            ensure_parent(path)?;
            fs::write(path, result.json() + "\n").map_err(|e| e.to_string())?;
        }
        Ok(result)
    }
}
fn run() -> Result<(), String> {
    let Some(options) = options()? else {
        return Ok(());
    };
    if options.serve {
        let mut compiler = Compiler::new(&options);
        let stdin = io::stdin();
        let mut stdout = io::stdout().lock();
        for line in stdin.lock().lines() {
            let line = line.map_err(|e| e.to_string())?;
            if line == "quit" {
                break;
            }
            let fields: Vec<_> = line.split('\t').collect();
            let result = if fields.len() == 4
                && fields[0] == "compile"
                && !fields[1].is_empty()
                && !fields[2].is_empty()
            {
                compiler.compile(
                    Path::new(fields[1]),
                    Path::new(fields[2]),
                    None,
                    (!fields[3].is_empty()).then(|| Path::new(fields[3])),
                )
            } else {
                Err("Expected compile<TAB>SOURCE<TAB>OUTPUT<TAB>REPORT; paths cannot contain tabs or newlines".into())
            };
            let response = match result {
                Ok(report) => report.json(),
                Err(error) => format!("{{\"status\":\"error\",\"error\":{}}}", json_string(&error)),
            };
            writeln!(stdout, "{response}").map_err(|e| e.to_string())?;
            stdout.flush().map_err(|e| e.to_string())?;
        }
        return Ok(());
    }
    let source = options.source.as_ref().unwrap();
    if options.output.is_none() && options.backend.is_none() {
        let emit = options
            .emit
            .as_ref()
            .ok_or("--emit-llvm or --output is required")?;
        let program = frontend::parse(&fs::read_to_string(source).map_err(|e| e.to_string())?)?;
        ensure_parent(emit)?;
        fs::write(emit, llvm::emit(&program)?).map_err(|e| e.to_string())?;
        return Ok(());
    }
    let output = options
        .output
        .as_ref()
        .ok_or("Native compilation requires --output")?;
    let mut compiler = Compiler::new(&options);
    println!(
        "{}",
        compiler
            .compile(
                source,
                output,
                options.emit.as_deref(),
                options.report.as_deref()
            )?
            .json()
    );
    Ok(())
}
fn main() {
    if let Err(error) = run() {
        eprintln!("gpu-rust-compiler: {error}");
        process::exit(1);
    }
}
